"""The config loader (PL-01 and PL-03 step 1).

A run config is a TOML file:

    world = "snake"
    variant = "default"          # optional, "default"
    budget = 200000              # world steps
    device = "cpu"               # optional, "cpu"

    [methods.snake]              # one table per team
    method = "dqn"
    lr = 0.001                   # optional: any setting the method declares

    [check_settings.dqn]         # optional: settings for the check world only (AD-09)
    hidden = 16
"""

import tomllib
from collections.abc import Mapping, Sequence
from pathlib import Path
from typing import Any, Literal, cast

from rllab.core.types import MethodConfig, Settings
from rllab.train.types import RunConfig

MethodName = Literal["dqn", "ppo"]
Value = int | float | str | bool

METHOD_DEFAULTS: Mapping[MethodName, Settings] = {
    "dqn": {
        "lr": 0.001,
        "gamma": 0.99,
        "hidden": 64,
        "epsilon_start": 1.0,
        "epsilon_end": 0.05,
        "epsilon_decay_steps": 20000,
    },
    "ppo": {
        "lr": 0.0003,
        "gamma": 0.99,
        "hidden": 64,
        "rollout_steps": 2048,
        "init_log_std": -0.5,
    },
}

WORLD_VARIANTS: Mapping[str, tuple[str, ...]] = {
    "snake": ("default",),
    "fish": ("one-fish", "many-fish", "local-sight"),
    "prey": ("default",),
}

TOP_KEYS = ("world", "variant", "budget", "device", "methods", "check_settings")


def load_run_configs(path: Path, seeds: Sequence[int]) -> list[RunConfig]:
    """One `RunConfig` per seed from the TOML at `path`, named `<stem>-s<seed>`."""
    with path.open("rb") as f:
        raw = tomllib.load(f)
    _check_keys(raw, TOP_KEYS, "config")
    world, variant = _world_variant(raw)
    methods = {team: _method_config(team, table) for team, table in _table(raw, "methods").items()}
    if not methods:
        raise ValueError("config: [methods] names no team")
    checks = {
        name: _settings(_method_name(name), table, f"check_settings.{name}")
        for name, table in _table(raw, "check_settings").items()
    }
    return [
        RunConfig(
            name=f"{path.stem}-s{seed}",
            world=world,
            variant=variant,
            methods=methods,
            seed=seed,
            budget=_int(raw, "budget"),
            check_settings=checks,
            device=str(raw.get("device", "cpu")),
        )
        for seed in seeds
    ]


def _check_keys(table: Mapping[str, Any], allowed: Sequence[str], where: str) -> None:
    unknown = [key for key in table if key not in allowed]
    if unknown:
        raise ValueError(f"{where}: unknown key {', '.join(map(repr, unknown))}")


def _world_variant(raw: Mapping[str, Any]) -> tuple[str, str]:
    world = raw.get("world")
    if world not in WORLD_VARIANTS:
        raise ValueError(f"config: unknown world {world!r}")
    variant = raw.get("variant", "default")
    if variant not in WORLD_VARIANTS[world]:
        raise ValueError(f"config: unknown variant {variant!r} of world {world!r}")
    return str(world), str(variant)


def _int(raw: Mapping[str, Any], key: str) -> int:
    value = raw.get(key)
    if not isinstance(value, int) or isinstance(value, bool):
        raise ValueError(f"config: {key!r} must be an integer, got {value!r}")
    return value


def _table(raw: Mapping[str, Any], key: str) -> dict[str, Any]:
    value = raw.get(key, {})
    if not isinstance(value, dict):
        raise ValueError(f"config: {key!r} must be a table")
    return cast(dict[str, Any], value)


def _method_name(name: object) -> MethodName:
    if name not in METHOD_DEFAULTS:
        raise ValueError(f"unknown method {name!r}")
    return cast(MethodName, name)


def _method_config(team: str, table: object) -> MethodConfig:
    if not isinstance(table, dict):
        raise ValueError(f"methods.{team} must be a table")
    entries = cast(dict[str, Any], table)
    method = _method_name(entries.get("method"))
    given = {key: value for key, value in entries.items() if key != "method"}
    overrides = _settings(method, given, f"methods.{team}")
    return MethodConfig(method=method, settings={**METHOD_DEFAULTS[method], **overrides})


def _settings(method: MethodName, table: object, where: str) -> dict[str, Value]:
    if not isinstance(table, dict):
        raise ValueError(f"{where} must be a table")
    entries = cast(dict[str, Any], table)
    _check_keys(entries, tuple(METHOD_DEFAULTS[method]), where)
    for key, value in entries.items():
        if not isinstance(value, Value):
            raise ValueError(f"{where}: {key!r} must be a number, string or boolean")
    return dict(entries)

